using Captovix;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
internal static class Program{
 [STAThread]static int Main(){int count=0;void Check(bool x,string n){if(!x)throw new Exception(n);count++;Console.WriteLine("PASS "+n);}Window? window=null;
 try{var a=MockupStudio.Create(new(30,40,280,23),new(0,0,800,500),new("#FFFFFF","#FFFFFF","#0000FF",1));a.Mockup!.FromScan=true;a.Mockup.Type=MockupKind.Label;a.FontFamily="Times New Roman";a.FontSize=18;a.Bold=true;a.Italic=true;a.Text="01350006 - Nguyen Phi Long";var original=MockupEditing.Read(a);double width=EditorRenderer.MockupEditingWidth(a);var box=new TextBox{FontFamily=EditorRenderer.TextFont(a),FontSize=a.FontSize,FontStyle=FontStyles.Italic,FontWeight=FontWeights.Bold,Padding=new(0),BorderThickness=new(0),TextWrapping=TextWrapping.Wrap,Width=width+4,Text=a.Text};box.Measure(new(double.PositiveInfinity,double.PositiveInfinity));box.Arrange(new(0,0,width+4,100));box.UpdateLayout();Check(box.LineCount==1,"Scanned line remains one line in native TextBox at original style");Check(MockupEditing.Read(a)==original&&a.TextWidth==0,"Opening inline layout does not mutate font, frame or content");EditorRenderer.SetMockupText(a,a.Text+" + new content that exceeds original editing frame and must wrap onto a second line",width);var layout=EditorRenderer.TextLayout(a);Check(layout.Height>EditorRenderer.TextLayout(a,a.Text).Height,"New text exceeding fixed baseline width wraps in renderer");Check(a.FontSize==18&&a.Italic&&a.Bold&&a.TextColor=="#0000FF","Wrap does not scale font or change color");
 var manual=a.Copy();manual.Mockup!.FromScan=false;manual.Mockup.Type=MockupKind.Button;manual.TextWidth=0;Check(EditorRenderer.MockupEditingWidth(manual)==EditorRenderer.TextContent(manual).Width,"Existing wrapped button text keeps its content frame during editing");
 var assembly=typeof(MainWindow).Assembly;var scrolling=assembly.GetType("Captovix.AppScrolling")!;scrolling.GetMethod("Initialize")!.Invoke(null,null);var list=new ListBox{Height=260,Width=300};VirtualizingPanel.SetScrollUnit(list,ScrollUnit.Pixel);ScrollViewer.SetCanContentScroll(list,true);var factory=new FrameworkElementFactory(typeof(VirtualizingStackPanel));factory.SetValue(VirtualizingPanel.ScrollUnitProperty,ScrollUnit.Pixel);list.ItemsPanel=new(factory);for(int i=0;i<1000;i++)list.Items.Add(new ListBoxItem{Content="Image "+i,Height=100});window=new Window{Width=400,Height=400,Content=list,ShowInTaskbar=false};window.Show();window.UpdateLayout();ScrollViewer Find(DependencyObject n){if(n is ScrollViewer v)return v;for(int i=0;i<VisualTreeHelper.GetChildrenCount(n);i++){try{return Find(VisualTreeHelper.GetChild(n,i));}catch(InvalidOperationException){}}throw new InvalidOperationException();}var scroll=Find(list);scroll.ScrollToVerticalOffset(300);window.UpdateLayout();var wheel=new MouseWheelEventArgs(Mouse.PrimaryDevice,Environment.TickCount,-120){RoutedEvent=Mouse.PreviewMouseWheelEvent,Source=scroll};scroll.RaiseEvent(wheel);window.UpdateLayout();Check(scroll.VerticalOffset>300&&scroll.VerticalOffset<600,"One wheel step scrolls pixels and does not jump to last image");
 var horizontal=new FrameworkElementFactory(typeof(VirtualizingStackPanel));horizontal.SetValue(VirtualizingPanel.ScrollUnitProperty,ScrollUnit.Pixel);horizontal.SetValue(VirtualizingStackPanel.OrientationProperty,Orientation.Horizontal);list.ItemsPanel=new(horizontal);ScrollViewer.SetHorizontalScrollBarVisibility(list,ScrollBarVisibility.Auto);ScrollViewer.SetVerticalScrollBarVisibility(list,ScrollBarVisibility.Disabled);foreach(ListBoxItem entry in list.Items){entry.Width=100;entry.Height=70;}window.UpdateLayout();scroll=Find(list);scroll.ScrollToHorizontalOffset(300);window.UpdateLayout();scroll.RaiseEvent(new MouseWheelEventArgs(Mouse.PrimaryDevice,Environment.TickCount,-120){RoutedEvent=Mouse.PreviewMouseWheelEvent,Source=scroll});window.UpdateLayout();Check(scroll.HorizontalOffset>300&&scroll.HorizontalOffset<600,"Horizontal-only filmstrip uses normal wheel distance");
 var config=assembly.GetType("Captovix.MockupCaptureWindow")!;var dialog=(Window)Activator.CreateInstance(config,new object[]{new PixelRect(0,0,800,500),(Func<CancellationToken,Task<System.Windows.Media.Imaging.BitmapSource>>)(_=>Task.FromResult(ImageTransfer.Bitmap(800,500,new byte[800*500*4])))})!;Check(dialog.Title.Contains("Cấu hình Mockup"),"Mockup opens dedicated configuration window");dialog.Close();Console.WriteLine($"{count} native workflow polish checks passed; external clipboard/drop targets and real IME still need manual acceptance.");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{window?.Close();StaImageWorker.Stop();}}
}
